import { createHash } from "node:crypto";
import type { Database } from "@firra/db-types";
import type { SupabaseClient } from "@supabase/supabase-js";
import { createClient } from "@supabase/supabase-js";

/** `frm_` plus 256 random bits in hex, generated by `create_mcp_token` (docs/plans/f-mcp.md F-D4). */
const TOKEN_FORMAT = /^frm_[0-9a-f]{64}$/;

export interface McpTokenRecord {
  id: string;
  workspaceId: string;
  userId: string;
  scopes: readonly string[];
}

/** Service-role lookup of a presented secret. Null for unknown, revoked or expired tokens. */
export interface McpTokenStore {
  resolve(secret: string, now: Date): Promise<McpTokenRecord | null>;
}

/** sha256 of the secret as PostgREST's bytea literal. */
export function tokenHashLiteral(secret: string): string {
  return `\\x${createHash("sha256").update(secret, "utf8").digest("hex")}`;
}

const TOUCH_EVERY_MS = 60_000;

export class SupabaseMcpTokenStore implements McpTokenStore {
  private readonly touched = new Map<string, number>();

  constructor(private readonly db: SupabaseClient<Database>) {}

  async resolve(secret: string, now: Date): Promise<McpTokenRecord | null> {
    if (!TOKEN_FORMAT.test(secret)) return null;
    const { data, error } = await this.db
      .from("mcp_token")
      .select("id, workspace_id, user_id, scopes, expires_at, revoked_at")
      .eq("token_hash", tokenHashLiteral(secret))
      .maybeSingle();
    if (error) throw new Error(`mcp token lookup failed: ${error.code}`);
    if (!data) return null;
    if (data.revoked_at !== null || new Date(data.expires_at) <= now) return null;
    await this.touch(data.id, now);
    return {
      id: data.id,
      workspaceId: data.workspace_id,
      userId: data.user_id,
      scopes: data.scopes,
    };
  }

  /** `last_used_at` is informational: at most one write a minute per token, failures ignored. */
  private async touch(id: string, now: Date): Promise<void> {
    const last = this.touched.get(id) ?? 0;
    if (now.getTime() - last < TOUCH_EVERY_MS) return;
    this.touched.set(id, now.getTime());
    try {
      await this.db.from("mcp_token").update({ last_used_at: now.toISOString() }).eq("id", id);
    } catch {
      // Informational only: a failed write must not turn a valid token into an error.
    }
  }
}

/** Short-lived session of a token's user, so reads run through RLS like any other caller. */
export interface SessionMinter {
  mint(userId: string, now: Date): Promise<string>;
}

const MAX_CACHE_MS = 45 * 60_000;
const REFRESH_MARGIN_MS = 5 * 60_000;

/**
 * Mints a session server-side: the service role creates a one-time sign-in link for the user and
 * the publishable client redeems it (docs/plans/f-mcp.md F-D5). The access token lives in memory
 * only, for at most 45 minutes; it is never stored, logged or returned to a client.
 */
export class SupabaseSessionMinter implements SessionMinter {
  private readonly cache = new Map<string, { token: string; until: number }>();

  constructor(
    private readonly admin: SupabaseClient<Database>,
    private readonly url: string,
    private readonly publishableKey: string,
  ) {}

  async mint(userId: string, now: Date): Promise<string> {
    const cached = this.cache.get(userId);
    if (cached && cached.until > now.getTime()) return cached.token;

    const { data: user, error: userError } = await this.admin.auth.admin.getUserById(userId);
    const email = user.user?.email;
    if (userError || !email) throw new Error("session mint failed: user");
    const { data: link, error: linkError } = await this.admin.auth.admin.generateLink({
      type: "magiclink",
      email,
    });
    if (linkError) throw new Error("session mint failed: link");

    const anon = createClient(this.url, this.publishableKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const { data: session, error } = await anon.auth.verifyOtp({
      token_hash: link.properties.hashed_token,
      type: "magiclink",
    });
    if (error || !session.session) throw new Error("session mint failed: verify");

    const expiresAt = (session.session.expires_at ?? 0) * 1000 - REFRESH_MARGIN_MS;
    const until = Math.min(now.getTime() + MAX_CACHE_MS, expiresAt);
    this.cache.set(userId, { token: session.session.access_token, until });
    return session.session.access_token;
  }
}
